import { QueryClient, queryOptions, useQuery, useQueryClient } from '@pyreon/query'
import { signal } from '@pyreon/reactivity'
type User = { id: number; name: string }

// declare once...
const userQuery = (id: number) =>
  queryOptions({ queryKey: ['user', id], queryFn: () => fetchUser(id), staleTime: 60_000 })

// ...use in a component (the factory runs inside the accessor, so it stays reactive)
const selected = signal(1)
function UserName() {
  const user = useQuery(() => userQuery(selected()))
  const client = useQueryClient()
  return (
    <a onMouseEnter={() => client.prefetchQuery(userQuery(selected() + 1))}>
      {() => user.data()?.name}
    </a>
  )
}

// ...and in the client, typed without a generic
function rename(client: QueryClient, id: number, name: string) {
  client.setQueryData(userQuery(id).queryKey, (u) => u && { ...u, name })
  return client.getQueryData(userQuery(id).queryKey) // User | undefined
}

import { useQuery, useSubscription } from '@pyreon/query'
type Order = { id: string; status: string }

function Orders() {
  const orders = useQuery(() => ({ queryKey: ['orders'], queryFn: fetchOrders }))
  const live = useSubscription({
    url: 'wss://api.example.com/ws',
    onMessage: (event, client) => {
      const msg = JSON.parse(event.data) as { type: string; order: Order }
      if (msg.type === 'order-updated') {
        client.setQueryData<Order[]>(['orders'], (list) =>
          list?.map((o) => (o.id === msg.order.id ? msg.order : o)),
        )
      }
    },
  })
  return (
    <p>
      {() => orders.data()?.length ?? 0} orders · socket {() => live.status()}
    </p>
  )
}
